// 同一完整字段表驱动JSON、checkpoint及只读投影；冷读不从当前市场补批准。
#include "resident/checkpoint/checkpoint_decode_lifecycle.hpp"
#include "public_market_authority.hpp"
#include "resident/domains/organization/organization_lifecycle_codec_detail.hpp"
namespace hanmo::resident {namespace {
using namespace organization_lifecycle_fields;
template<class C>Status spans(C& c,const StableId& name,std::vector<MomentSpan>& rows){return c.sequence(name,rows,[](auto& v,auto& span){v.object("from",[&](auto& a){return exact_fields::moment(a,span.from);});return v.object("to",[&](auto& a){return exact_fields::moment(a,span.to);});});}
template<class C>Status acting(C& c,ActingAuthority& a){c.field("organization_id",a.organization_id);c.field("office_id",a.office_id);c.field("authority_epoch",a.authority_epoch);return c.field("actor_id",a.actor_id);}
template<class C>Status basis_ref(C& c,AuthorityBasisRef& r){c.object("issued_source",[&](auto& v){return source(v,r.issued_source);});c.field("source_schema",r.source_schema);return c.status().ok&&r.source_schema!=1?c.reject("UnsupportedPublicMarketAuthorityBasisSchema"):c.status();}
template<class C>Status policy_fields(C& c,PublicMarketAuthorityPolicy& p){c.object("policy_ref",[&](auto& v){return rule(v,p.policy_ref);});c.object("market_definition_ref",[&](auto& v){return rule(v,p.market_definition_ref);});c.object("opening_rule_ref",[&](auto& v){return rule(v,p.opening_rule_ref);});c.object("usage_rule_ref",[&](auto& v){return rule(v,p.usage_rule_ref);});c.field("organization_id",p.organization_id);c.field("asset_id",p.asset_id);c.object("original_asset_initialization_ref",[&](auto& v){return source(v,p.original_asset_initialization_ref);});c.object("original_asset_right_ref",[&](auto& v){return source(v,p.original_asset_right_ref);});c.object("original_usage_right_ref",[&](auto& v){return source(v,p.original_usage_right_ref);});spans(c,"allowed_opening_intervals",p.allowed_opening_intervals);return spans(c,"allowed_usage_intervals",p.allowed_usage_intervals);}
template<class C>Status record_fields(C& c,PublicMarketAuthorityRecord& r){c.field("id",r.id);c.object("policy_ref",[&](auto& v){return rule(v,r.policy_ref);});c.object("market_definition_ref",[&](auto& v){return rule(v,r.market_definition_ref);});c.field("revision",r.revision);c.optional("previous_source_ref",r.previous_source_ref,[](auto& v,auto& s){return source(v,s);});{static constexpr const char* tags[]={"issued","revised","ended"};enum_field(c,"decision",r.decision,tags);}c.object("issuer",[&](auto& v){return acting(v,r.issuer);});c.object("original_asset_initialization_ref",[&](auto& v){return source(v,r.original_asset_initialization_ref);});c.object("original_asset_right_ref",[&](auto& v){return source(v,r.original_asset_right_ref);});c.object("original_usage_right_ref",[&](auto& v){return source(v,r.original_usage_right_ref);});c.object("opening_rule_ref",[&](auto& v){return rule(v,r.opening_rule_ref);});c.object("usage_rule_ref",[&](auto& v){return rule(v,r.usage_rule_ref);});spans(c,"committed_opening_intervals",r.committed_opening_intervals);spans(c,"valid_usage_intervals",r.valid_usage_intervals);c.object("authority_basis_ref",[&](auto& v){return basis_ref(v,r.authority_basis_ref);});return c.object("issued_at",[&](auto& v){return exact_fields::moment(v,r.issued_at);});}
template<class C>Status state_fields(C& c,PublicMarketAuthorityState& s){Integer schema=1;c.field("schema_version",schema);if(!c.status().ok)return c.status();if(schema!=1)return c.reject("UnsupportedPublicMarketAuthoritySchema");return table(c,"authorizations",s.authorizations,[](auto& v,auto& row){return record_fields(v,row);});}
template<class C>Status catalog_fields(C& c,PublicMarketAuthorityCatalog& catalog){Integer schema=1;c.field("schema_version",schema);if(!c.status().ok)return c.status();if(schema!=1)return c.reject("UnsupportedPublicMarketAuthorityCatalogSchema");return table(c,"policies",catalog.policies,[](auto& v,auto& row){return policy_fields(v,row);});}
}
Status visit_public_market_authority(CodecVisitor& c,PublicMarketAuthorityState& s){return state_fields(c,s);}
Status emit_public_market_authority_projection(ProjectionWriter& sink,std::string_view name,const PublicMarketAuthorityState& s){return emit_projection_record<ActorFoundationProjectionArchive>(sink,name,s,[](auto& c,auto& value){return state_fields(c,value);});}
Outcome<BoundaryValue> encode_public_market_authority(const PublicMarketAuthorityState& s){BoundaryValue out;BoundaryProjectionWriter sink(out);auto valid=emit_public_market_authority_projection(sink,"",s);if(valid.ok)valid=sink.finish();return {valid.ok,std::move(out),valid.error};}
Outcome<PublicMarketAuthorityState> decode_public_market_authority(const BoundaryValue& value){PublicMarketAuthorityState out;ActorFoundationJsonVisitor reader(value);auto valid=state_fields(reader,out);if(valid.ok)valid=reader.finish();return {valid.ok,std::move(out),valid.error};}
Outcome<BoundaryValue> encode_public_market_authority_catalog(const PublicMarketAuthorityCatalog& s){BoundaryValue out;BoundaryProjectionWriter sink(out);auto valid=emit_projection_record<ActorFoundationProjectionArchive>(sink,"",s,[](auto& c,auto& value){return catalog_fields(c,value);});if(valid.ok)valid=sink.finish();return {valid.ok,std::move(out),valid.error};}
Outcome<PublicMarketAuthorityCatalog> decode_public_market_authority_catalog(const BoundaryValue& value,const CatalogIdentity& identity){PublicMarketAuthorityCatalog out;out.identity=identity;ActorFoundationJsonVisitor reader(value);auto valid=catalog_fields(reader,out);if(valid.ok)valid=reader.finish();return {valid.ok,std::move(out),valid.error};}
}
